import { test, expect } from '@playwright/test';

test.describe('Touch Targets Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('Verify touch targets are large enough', async ({ page }) => {
    const touchTarget = page.getByRole('button', { name: /submit/i });
    const boundingBox = await touchTarget.boundingBox();
    expect(boundingBox).not.toBeNull();
    expect(boundingBox!.width).toBeGreaterThanOrEqual(48);
    expect(boundingBox!.height).toBeGreaterThanOrEqual(48);
  });

  test('Check touch target spacing', async ({ page }) => {
    const firstTarget = page.getByRole('button', { name: /submit/i });
    const secondTarget = page.getByRole('button', { name: /cancel/i });

    const firstBox = await firstTarget.boundingBox();
    const secondBox = await secondTarget.boundingBox();

    expect(firstBox).not.toBeNull();
    expect(secondBox).not.toBeNull();

    const distance = Math.abs(firstBox!.x - secondBox!.x);
    expect(distance).toBeGreaterThanOrEqual(16); // Minimum spacing
  });
});
